CREATE FUNCTION public.message_test_assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',message; END IF; RAISE NOTICE 'PASS: %',message; END $$;
CREATE FUNCTION public.message_test_reject(statement text,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS: %',message; RETURN; END; RAISE EXCEPTION 'FAIL: expected rejection: %',message; END $$;
INSERT INTO auth.users(id,email,raw_user_meta_data,email_confirmed_at) VALUES('c8555555-5555-4555-8555-555555555555','message-coordinator@example.invalid','{}',now());
SELECT message_test_assert(NOT has_table_privilege('authenticated','provider_booking_messages','INSERT,UPDATE,DELETE'),'message contents have no direct client writes');
SELECT message_test_assert(NOT has_table_privilege('authenticated','provider_booking_thread_reads','INSERT,UPDATE,DELETE'),'read cursors have no direct client writes');
SELECT message_test_assert(NOT has_function_privilege('anon','send_booking_message(uuid,text,uuid)','EXECUTE'),'anonymous message sending denied');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','c8222222-2222-4222-8222-222222222222',true);
SELECT set_config('message_test.booking',request_provider_booking(current_setting('message_test.service')::uuid,2,current_setting('message_test.start')::timestamptz,gen_random_uuid(),'c9111111-1111-4111-8111-111111111111',NULL,'08012345678','','')::text,true);
SELECT message_test_assert((SELECT can_send AND unread_count=0 AND last_ordinal=0 FROM get_booking_thread_state(current_setting('message_test.booking')::uuid)),'a customer can open an empty eligible conversation');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,E'\n\t  ',gen_random_uuid()) $q$,'whitespace-only messages rejected');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,repeat('x',2001),gen_random_uuid()) $q$,'oversized messages rejected');
SELECT set_config('message_test.key',gen_random_uuid()::text,true);
SELECT set_config('message_test.first',send_booking_message(current_setting('message_test.booking')::uuid,'  Private arrival question  ',current_setting('message_test.key')::uuid)::text,true);
SELECT message_test_assert(send_booking_message(current_setting('message_test.booking')::uuid,'Private arrival question',current_setting('message_test.key')::uuid)=current_setting('message_test.first')::uuid,'message retry is idempotent after server normalization');
SELECT message_test_assert((SELECT count(*)=1 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'retry creates no duplicate message');
SELECT message_test_assert((SELECT ordinal=1 AND sender_id=auth.uid() AND sender_role='customer' AND body='Private arrival question' FROM provider_booking_messages WHERE id=current_setting('message_test.first')::uuid),'server derives message identity, role and thread-local order');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Changed payload',current_setting('message_test.key')::uuid) $q$,'reusing a key for different text is rejected');
SELECT message_test_assert((SELECT unread_count=0 FROM get_booking_thread_state(current_setting('message_test.booking')::uuid)),'own messages do not count as unread');
SELECT set_config('request.jwt.claim.sub','c8333333-3333-4333-8333-333333333333',true);
SELECT message_test_assert((SELECT count(*)=0 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'unrelated customers cannot read messages');
SELECT message_test_reject($q$ SELECT get_booking_thread_state(current_setting('message_test.booking')::uuid) $q$,'unknown conversation does not return a fake empty state');
SELECT message_test_reject($q$ SELECT mark_booking_thread_read(current_setting('message_test.booking')::uuid,1) $q$,'unrelated accounts cannot acknowledge another conversation');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Unauthorized message',gen_random_uuid()) $q$,'unrelated customer cannot send into known booking');
SELECT set_config('request.jwt.claim.sub','c8111111-1111-4111-8111-111111111111',true);
SELECT message_test_assert((SELECT unread_count=1 FROM get_booking_thread_state(current_setting('message_test.booking')::uuid)),'provider sees the customer message as unread');
SELECT message_test_assert((SELECT count(*)=1 FROM notifications WHERE booking_message_id=current_setting('message_test.first')::uuid AND link='/appointments/'||current_setting('message_test.booking')||'#messages' AND message NOT LIKE '%Private arrival question%'),'message alerts link to the thread without copying its body');
SELECT mark_booking_thread_read(current_setting('message_test.booking')::uuid,1);
SELECT mark_booking_thread_read(current_setting('message_test.booking')::uuid,0);
SELECT message_test_assert((SELECT unread_count=0 AND last_read_ordinal=1 FROM get_booking_thread_state(current_setting('message_test.booking')::uuid)),'older read requests cannot move the cursor backward');
SELECT message_test_assert((SELECT is_read FROM notifications WHERE booking_message_id=current_setting('message_test.first')::uuid),'conversation acknowledgement marks only matching message alerts read');
SELECT message_test_assert((SELECT count(*)=1 FROM notifications WHERE booking_id=current_setting('message_test.booking')::uuid AND booking_message_id IS NULL AND NOT is_read),'reading a message does not acknowledge booking status alerts');
SELECT message_test_reject($q$ SELECT mark_booking_thread_read(current_setting('message_test.booking')::uuid,999) $q$,'unseen or nonexistent message ordinals cannot be acknowledged');
SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Provider coordination reply',gen_random_uuid());
SELECT message_test_assert((SELECT count(*)=2 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'participant replies append without overwriting history');
SELECT set_config('message_test.invite',invite_provider_team_member(current_setting('message_test.org')::uuid,'message-coordinator@example.invalid','staff')::text,true);
SELECT set_config('request.jwt.claim.sub','c8555555-5555-4555-8555-555555555555',true);
SELECT respond_provider_team_invitation(current_setting('message_test.invite')::uuid,1,'accept');
SELECT message_test_assert((SELECT count(*)=2 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'active coordinator can read the scoped conversation');
SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Coordinator visit reply',gen_random_uuid());
SELECT message_test_assert((SELECT sender_role='provider_team' FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid AND ordinal=3),'coordinator messages are not labelled as veterinary or clinical actions');
SELECT set_config('request.jwt.claim.sub','c8444444-4444-4444-8444-444444444444',true);
SELECT message_test_assert((SELECT count(*)=3 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'active support administrators can inspect an authorized booking thread');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Admin impersonation',gen_random_uuid()) $q$,'nonparticipant administrator cannot impersonate a customer or provider');
SELECT set_config('request.jwt.claim.sub','c8222222-2222-4222-8222-222222222222',true);
SELECT message_test_assert((SELECT unread_count=2 FROM get_booking_thread_state(current_setting('message_test.booking')::uuid)),'customer unread state includes both provider replies');
SELECT mark_booking_thread_read(current_setting('message_test.booking')::uuid,3);
SELECT set_config('request.jwt.claim.sub','c8111111-1111-4111-8111-111111111111',true);
SELECT update_provider_team_member((SELECT id FROM list_provider_team(current_setting('message_test.org')::uuid) WHERE user_id='c8555555-5555-4555-8555-555555555555'),1,'staff',false);
SELECT set_config('request.jwt.claim.sub','c8555555-5555-4555-8555-555555555555',true);
SELECT message_test_assert((SELECT count(*)=0 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'revocation removes delegated message reads');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Revoked member reply',gen_random_uuid()) $q$,'revoked coordinator cannot send or replay into the thread');
SELECT set_config('request.jwt.claim.sub','c8222222-2222-4222-8222-222222222222',true);
DO $$ BEGIN FOR i IN 1..9 LOOP PERFORM send_booking_message(current_setting('message_test.booking')::uuid,'Rate fixture '||i,gen_random_uuid()); END LOOP; END $$;
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Excess message',gen_random_uuid()) $q$,'per-account message burst limits enforced');
SELECT set_config('request.jwt.claim.sub','c8111111-1111-4111-8111-111111111111',true);
SELECT respond_provider_booking(current_setting('message_test.booking')::uuid,1,'declined','Cannot offer this appointment.');
SELECT message_test_assert((SELECT NOT can_send FROM get_booking_thread_state(current_setting('message_test.booking')::uuid)),'declined booking conversations become read-only');
SELECT message_test_reject($q$ SELECT send_booking_message(current_setting('message_test.booking')::uuid,'Closed thread reply',gen_random_uuid()) $q$,'read-only threads reject new messages');
SELECT message_test_assert((SELECT count(*)=12 FROM provider_booking_messages WHERE booking_id=current_setting('message_test.booking')::uuid),'closed threads retain their immutable message history');
RESET ROLE;
SELECT message_test_assert((SELECT count(*)=12 FROM audit_logs WHERE action='provider_booking_message_sent' AND entity_id=current_setting('message_test.booking')::uuid),'message audit records are generated once per committed message');
SELECT message_test_assert((SELECT count(*)=0 FROM notifications WHERE booking_id=current_setting('message_test.booking')::uuid AND booking_message_id IS NOT NULL AND message LIKE '%Private arrival question%'),'notification previews never contain message text');
